import Foundation

// This file contains the known good data for empty.art files
struct EmptyArtData {
    static let hexString = ""
    
    static let data: [UInt8] = {
        return stride(from: 0, to: hexString.count, by: 2).compactMap { offset -> UInt8? in
            let startIndex = hexString.index(hexString.startIndex, offsetBy: offset)
            let endIndex = hexString.index(startIndex, offsetBy: 2)
            let byteSubstring = hexString[startIndex..<endIndex]
            
            // Convert the substring to a String
            let byteString = String(byteSubstring)
            
            // Convert the string to a UInt8
            return UInt8(byteString, radix: 16)
        }
    }()
}
